def recipes():
    stage = shared.split_graph_with_results()
    for key in ('13', '29'):
        stage[key]['class_type'] = 'MiniMaxH3StageReuseEXPT8'
        stage[key]['inputs']['mode'] = 'disabled'
    # Reuse owns persistence when explicitly enabled; no redundant Save output.
    stage.pop('50')
    stage.pop('51')
    stage['30']['inputs']['sampled_av_latent'] = ['29', 0]
    stage['33'] = {'class_type':'PreviewAny', 'inputs':{'source':['13', 3]}}
    stage['34'] = {'class_type':'PreviewAny', 'inputs':{'source':['29', 3]}}
    stage['16']['inputs']['filename_prefix'] = 'Nov05/Stage_Reuse_EXP'
    return {'TaoMate_HD_2plus1_EXP':deepcopy(TAOMATE_GRAPH),
            'NAG_CFG1_EXP':deepcopy(NAG_GRAPH), 'Stage_Reuse_EXP':stage,
            **deepcopy(ADDITIONAL_GRAPHS), 'H3_SFX_Generate_EXP':deepcopy(H3_SFX_GRAPH)}


def load_live_info():
    info = shared.load_live_info()
    import nodes
    from comfy_extras.nodes_custom_sampler import SplitSigmas
    from comfy_extras.nodes_mask import SolidMask
    from comfy_extras.nodes_video import LoadVideo
    for cls in (SplitSigmas, SolidMask, LoadVideo):
        name = cls.define_schema().node_id
        nodes.NODE_CLASS_MAPPINGS[name] = cls
        info[name] = shared.native_info(name, cls)
    for name in ('CLIPTextEncode', 'ImageScale', 'ImagePadForOutpaint'):
        info[name] = shared.native_info(name, nodes.NODE_CLASS_MAPPINGS[name])
    return json.loads(json.dumps(info))


def build_candidate(graph, info, name, note):
    """Serialize a supplied API recipe against live Core schema, preserving values."""
    graph, selected = shared.selected_frontend_schema(graph, info)
    # Core 0.44 serializes a separate hidden legacy SaveVideo codec fallback.
    # Materialize its native default *after* expanding format.codec, so the old
    # legacy-to-dynamic migration cannot overwrite the explicitly selected codec.
    for node in graph.values():
        if node['class_type'] != 'SaveVideo':
            continue
        legacy = info['SaveVideo'].get('input', {}).get('optional', {}).get('codec')
        if not legacy or legacy[0] != 'COMFY_DYNAMICCOMBO_V3' or not legacy[1].get('hidden'):
            continue
        choices = legacy[1]['options']
        keys = [choice['key'] for choice in choices]
        fallback = legacy[1].get('default', keys[0])
        node['inputs']['codec'] = fallback
        schema = selected['SaveVideo']
        schema['input']['optional']['codec'] = [keys, {**legacy[1], 'default': fallback}]
        schema['input_order']['optional'] = list(schema['input']['optional'])
    workflow = shared.convert(graph, selected, name + ' — unpublished EXP candidate')
    # Keep independent node cards from overlapping tall text/conditioning cards.
    columns = {}
    for node in workflow['nodes']:
        x = node['pos'][0]
        node['pos'][1] = columns.get(x, 0)
        node['size'][0] = 390
        node['size'][1] = max(node['size'][1], 240 if any(isinstance(v, str) and len(v) > 120
                                                       for v in node.get('widgets_values', [])) else 120)
        columns[x] = node['pos'][1] + node['size'][1] + 90
    note_id = workflow['last_node_id'] + 1
    workflow['nodes'].append({'id':note_id, 'type':'MarkdownNote', 'pos':[0, -350],
        'size':[1000, 270], 'flags':{}, 'order':note_id-1, 'mode':0, 'inputs':[], 'outputs':[],
        'properties':{'Node name for S&R':'MarkdownNote'}, 'widgets_values':[note],
        'title':'使用说明与验收范围 / 未发布候选'})
    workflow['last_node_id'] = note_id
    # Stay above the native frontend's simplified-node zoom threshold.
    workflow['extra']['ds'] = {'scale':.70, 'offset':[160, 450]}
    return graph, workflow, shared.audit_candidate(graph, workflow, selected), selected


def build(name, info):
    return build_candidate(recipes()[name], info, name, NOTES[name])


def main():
    import argparse
    import asyncio
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True, help='Directory for the candidate UI JSON files')
    parser.add_argument('--evidence', type=Path, required=True, help='New private directory for API/schema/check receipts')
    parser.add_argument('--only', action='append', choices=tuple(NOTES), help='Build only selected candidates; may repeat')
    args = parser.parse_args()
    evidence = args.evidence.resolve()
    if evidence.exists() or not evidence.is_relative_to((ROOT/'artifacts').resolve()):
        parser.error('Evidence must use a new directory under this checkout artifacts/')
    evidence.mkdir(parents=True)
    args.output.mkdir(parents=True, exist_ok=True)
    info = load_live_info()
    import execution
    import torch
    for name in args.only or NOTES:
        graph, workflow, audit, selected = build(name, info)
        valid = asyncio.run(execution.validate_prompt('nov05-build-'+name, graph, None))
        if not valid[0] or valid[3]:
            raise ValueError(valid)
        path = args.output/(name+'.json')
        if path.exists():
            raise FileExistsError('Candidate already exists; choose a new output directory: '+str(path))
        path.write_text(json.dumps(workflow, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
        (evidence/(name+'.api.json')).write_text(json.dumps(graph, ensure_ascii=False, indent=2), encoding='utf-8')
        (evidence/(name+'.schema.json')).write_text(json.dumps(selected, ensure_ascii=False), encoding='utf-8')
        (evidence/(name+'.receipt.json')).write_text(json.dumps({'serialization':audit, 'validation':valid,
            'cuda_initialized':torch.cuda.is_initialized(), 'actual_browser_roundtrip':False,
            'GPU_or_human_quality_qualified_by_this_builder':False}, ensure_ascii=False, indent=2), encoding='utf-8')
        print(path)



